import json
import re

_VALID_LEVELS = ("debug", "info", "warn", "error")

# Match token/password/secret followed by optional whitespace, '=', optional
# whitespace, and a value. The value is either a single/double quoted string or
# a non-empty run of characters up to whitespace, comma or semicolon.
_REDACT_RE = re.compile(
    r"(?i)\b(token|password|secret)\b[ \t]*=[ \t]*(?:"
    r"'[^']*'"
    r'|"[^"]*"'
    r"|[^\s,;]+"
    r")"
)


def _normalize_level(raw):
    if not isinstance(raw, str):
        raise ValueError("level must be a string")
    level = raw.strip().lower()
    if level == "warning":
        level = "warn"
    if level not in _VALID_LEVELS:
        raise ValueError("invalid level: %r" % raw)
    return level


def _parse_object(obj):
    if "level" in obj:
        level_raw = obj["level"]
    elif "severity" in obj:
        level_raw = obj["severity"]
    else:
        raise ValueError("object line missing level/severity")

    if "message" in obj:
        message = obj["message"]
    elif "msg" in obj:
        message = obj["msg"]
    else:
        raise ValueError("object line missing message/msg")

    if not isinstance(message, str):
        raise ValueError("message must be a string")

    return _normalize_level(level_raw), message


def _parse_line(line):
    if isinstance(line, dict):
        return _parse_object(line)

    if not isinstance(line, str):
        raise ValueError("line must be a string or object")

    if line.lstrip().startswith("{"):
        try:
            obj = json.loads(line)
        except ValueError:
            raise ValueError("JSON object line is not valid JSON")
        if not isinstance(obj, dict):
            raise ValueError("JSON object line must be an object")
        return _parse_object(obj)

    stripped = line.strip()
    if stripped == "":
        return None

    parts = stripped.split(None, 1)
    level = _normalize_level(parts[0])
    message = parts[1] if len(parts) > 1 else ""
    return level, message


def _redact(message):
    return _REDACT_RE.sub(
        lambda m: m.group(1).lower() + "=[REDACTED]", message
    )


def transform(payloads: list, contract: dict):
    if not isinstance(payloads, list) or len(payloads) != len(contract.get("inputs", [])):
        raise ValueError("payload count does not match contract inputs")

    name = contract["name"]
    data = payloads[0]
    if not isinstance(data, dict):
        raise ValueError("archive_logs payload must be an object")
    if "lines" not in data:
        raise ValueError("archive_logs payload missing lines")
    lines = data["lines"]
    if not isinstance(lines, list):
        raise ValueError("lines must be a list")

    out_lines = []
    counts = {}
    for line in lines:
        parsed = _parse_line(line)
        if parsed is None:
            continue
        level, message = parsed
        redacted = _redact(message)
        out_lines.append(level + " " + redacted)
        counts[level] = counts.get(level, 0) + 1

    return {
        "name": name,
        "result": {
            "lines": out_lines,
            "counts": dict(sorted(counts.items())),
        },
    }

