import math


def _ensure_finite(value):
    """Reject NaN/Infinity anywhere in a nested JSON value."""
    if isinstance(value, dict):
        for k, v in value.items():
            _ensure_finite(k)
            _ensure_finite(v)
    elif isinstance(value, list):
        for v in value:
            _ensure_finite(v)
    elif isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("non-finite number in payload")


def _nonempty_str(obj, key):
    if key not in obj:
        raise ValueError("missing field: %s" % key)
    value = obj[key]
    if not isinstance(value, str) or not value.strip():
        raise ValueError("field %s must be a non-empty string" % key)
    return value


def _nonneg_int(value, key):
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError("field %s must be a non-negative int" % key)
    return value


def _better(candidate, current):
    """True when candidate beats current under the objective ordering."""
    cv, cb, cs = candidate
    v, b, s = current
    if cv != v:
        return cv > v
    if cb != b:
        return cb < b
    return cs < s


def _solve(archives, budget, minimums):
    n = len(archives)
    options = []
    for a in archives:
        if a["hold"]:
            opts = [
                (a["id"], m["id"], m["bytes"], m["value"], a["category"])
                for m in a["modes"]
            ]
        else:
            opts = [None] + [
                (a["id"], m["id"], m["bytes"], m["value"], a["category"])
                for m in a["modes"]
            ]
        options.append(opts)

    best = None

    def rec(i, value, used_bytes, selected, cat_counts):
        nonlocal best
        if used_bytes > budget:
            return
        if i == n:
            for cat, need in minimums.items():
                if cat_counts.get(cat, 0) < need:
                    return
            sel = tuple(sorted(selected))
            candidate = (value, used_bytes, sel)
            if best is None or _better(candidate, best):
                best = candidate
            return

        for opt in options[i]:
            if opt is None:
                rec(i + 1, value, used_bytes, selected, cat_counts)
            else:
                aid, mid, b, v, cat = opt
                new_counts = dict(cat_counts)
                new_counts[cat] = new_counts.get(cat, 0) + 1
                rec(
                    i + 1,
                    value + v,
                    used_bytes + b,
                    selected + [(aid, mid)],
                    new_counts,
                )

    rec(0, 0, 0, [], {})

    if best is None:
        return {"feasible": False, "selected": [], "bytes": 0, "value": 0}

    value, used_bytes, sel = best
    return {
        "feasible": True,
        "selected": [{"archive": a, "mode": m} for (a, m) in sel],
        "bytes": used_bytes,
        "value": value,
    }


def transform(payloads: list, contract: dict):
    if not isinstance(payloads, list) or len(payloads) != len(contract.get("inputs", [])):
        raise ValueError("payload count does not match contract inputs")

    _ensure_finite(payloads)

    name = contract["name"]
    data = payloads[0]
    if not isinstance(data, dict):
        raise ValueError("retention_windows payload must be an object")
    if "archives" not in data:
        raise ValueError("retention_windows payload missing archives")
    if "budget" not in data:
        raise ValueError("retention_windows payload missing budget")
    if "minimums" not in data:
        raise ValueError("retention_windows payload missing minimums")

    archives_raw = data["archives"]
    if not isinstance(archives_raw, list):
        raise ValueError("archives must be a list")

    budget = _nonneg_int(data["budget"], "budget")

    minimums_raw = data["minimums"]
    if not isinstance(minimums_raw, dict):
        raise ValueError("minimums must be an object")
    minimums = {}
    for k, v in minimums_raw.items():
        if not isinstance(k, str) or not k.strip():
            raise ValueError("minimums keys must be non-empty strings")
        minimums[k] = _nonneg_int(v, "minimums value")

    archives = []
    seen_archive_ids = set()
    for item in archives_raw:
        if not isinstance(item, dict):
            raise ValueError("archive must be an object")
        archive_id = _nonempty_str(item, "id")
        if archive_id in seen_archive_ids:
            raise ValueError("duplicate archive id")
        seen_archive_ids.add(archive_id)

        category = _nonempty_str(item, "category")

        hold = item["hold"] if "hold" in item else None
        if not isinstance(hold, bool):
            raise ValueError("hold must be a bool")

        modes_raw = item["modes"] if "modes" in item else None
        if not isinstance(modes_raw, list):
            raise ValueError("modes must be a list")

        modes = []
        seen_mode_ids = set()
        for m in modes_raw:
            if not isinstance(m, dict):
                raise ValueError("mode must be an object")
            mode_id = _nonempty_str(m, "id")
            if mode_id in seen_mode_ids:
                raise ValueError("duplicate mode id in archive")
            seen_mode_ids.add(mode_id)
            modes.append(
                {
                    "id": mode_id,
                    "bytes": _nonneg_int(m["bytes"], "bytes"),
                    "value": _nonneg_int(m["value"], "value"),
                }
            )
        archives.append(
            {"id": archive_id, "category": category, "hold": hold, "modes": modes}
        )

    result = _solve(archives, budget, minimums)
    return {"name": name, "result": result}

