import fnmatch
import math


def _ensure_finite(value):
    """Reject NaN/Infinity anywhere in a nested JSON value."""
    if isinstance(value, dict):
        for k, v in value.items():
            _ensure_finite(k)
            _ensure_finite(v)
    elif isinstance(value, list):
        for v in value:
            _ensure_finite(v)
    elif isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("non-finite number in payload")


def _unwrap(payload):
    """A dict with exactly the keys name/result is an upstream component
    envelope; read its result. Any other object is a local object."""
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    return payload


def _nonempty_str(obj, key):
    if key not in obj:
        raise ValueError("missing field: %s" % key)
    value = obj[key]
    if not isinstance(value, str) or not value.strip():
        raise ValueError("field %s must be a non-empty string" % key)
    return value


def _specificity(rule):
    resource = rule["resource"]
    action = rule["action"]
    combined = resource + action
    return sum(1 for ch in combined if ch not in "*?[]")


def _rule_sort_key(rule):
    deny_first = 0 if rule["effect"] == "deny" else 1
    return (-rule["priority"], -rule["specificity"], deny_first, rule["id"])


def _match_request(rule, resource, action):
    return fnmatch.fnmatchcase(resource, rule["resource"]) and fnmatch.fnmatchcase(
        action, rule["action"]
    )


def _winning_rule(rules, resource, action):
    matches = [r for r in rules if _match_request(r, resource, action)]
    if not matches:
        return None
    return min(matches, key=_rule_sort_key)


def _parse_rules(rules_raw):
    if not isinstance(rules_raw, list):
        raise ValueError("rules must be a list")
    rules = []
    seen_ids = set()
    for item in rules_raw:
        if not isinstance(item, dict):
            raise ValueError("rule must be an object")
        rule = {
            "id": _nonempty_str(item, "id"),
            "resource": _nonempty_str(item, "resource"),
            "action": _nonempty_str(item, "action"),
            "priority": item["priority"] if "priority" in item else None,
            "effect": item["effect"] if "effect" in item else None,
        }
        if rule["id"] in seen_ids:
            raise ValueError("duplicate rule id")
        seen_ids.add(rule["id"])

        priority = rule["priority"]
        if isinstance(priority, bool) or not isinstance(priority, int):
            raise ValueError("priority must be an int")
        rule["priority"] = priority

        effect = rule["effect"]
        if effect not in ("allow", "deny"):
            raise ValueError("effect must be allow or deny")
        rule["effect"] = effect
        rule["specificity"] = _specificity(rule)
        rules.append(rule)
    return rules


def _parse_requests(requests_raw):
    if not isinstance(requests_raw, list):
        raise ValueError("requests must be a list")
    requests = []
    seen_ids = set()
    for item in requests_raw:
        if not isinstance(item, dict):
            raise ValueError("request must be an object")
        request = {
            "id": _nonempty_str(item, "id"),
            "archive": _nonempty_str(item, "archive"),
            "resource": _nonempty_str(item, "resource"),
            "action": _nonempty_str(item, "action"),
        }
        if request["id"] in seen_ids:
            raise ValueError("duplicate request id")
        seen_ids.add(request["id"])
        requests.append(request)
    return requests


def _parse_audit_marker(line, requests_by_id):
    if not isinstance(line, str):
        raise ValueError("log lines must be strings")

    request_id = None
    archive_id = None
    for token in line.split():
        if request_id is None and token.startswith("request="):
            request_id = token[len("request="):]
        if archive_id is None and token.startswith("archive="):
            archive_id = token[len("archive="):]

    if request_id is None:
        return None

    request = requests_by_id.get(request_id)
    if request is None:
        raise ValueError("unknown request in audit line")
    if archive_id is None or archive_id != request["archive"]:
        raise ValueError("audit marker conflict for request %s" % request_id)
    return request_id


def transform(payloads: list, contract: dict):
    if not isinstance(payloads, list) or len(payloads) != len(contract.get("inputs", [])):
        raise ValueError("payload count does not match contract inputs")

    _ensure_finite(payloads)

    name = contract["name"]

    policy = payloads[0]
    if not isinstance(policy, dict):
        raise ValueError("retention_policy payload must be an object")
    if "rules" not in policy:
        raise ValueError("retention_policy payload missing rules")
    if "requests" not in policy:
        raise ValueError("retention_policy payload missing requests")

    rules = _parse_rules(policy["rules"])
    requests = _parse_requests(policy["requests"])
    requests_by_id = {r["id"]: r for r in requests}

    logs_result = _unwrap(payloads[1])
    if not isinstance(logs_result, dict):
        raise ValueError("log_compatibility result must be an object")
    lines = logs_result.get("lines")
    if not isinstance(lines, list):
        raise ValueError("log lines must be a list")

    optimizer_result = _unwrap(payloads[2])
    if not isinstance(optimizer_result, dict):
        raise ValueError("retention_optimizer result must be an object")
    feasible = optimizer_result.get("feasible")
    if not isinstance(feasible, bool):
        raise ValueError("feasible must be a bool")
    selected = optimizer_result.get("selected")
    if not isinstance(selected, list):
        raise ValueError("selected must be a list")

    retained = set()
    for entry in selected:
        if not isinstance(entry, dict) or "archive" not in entry:
            raise ValueError("selected entry must be an object with archive")
        archive = entry["archive"]
        if not isinstance(archive, str) or not archive.strip():
            raise ValueError("selected archive must be a non-empty string")
        retained.add(archive)

    covered = set()
    for line in lines:
        marker = _parse_audit_marker(line, requests_by_id)
        if marker is None:
            continue
        if marker in covered:
            raise ValueError("duplicate request in audit lines")
        covered.add(marker)

    decisions = []
    allow = 0
    deny = 0
    for request in requests:
        if not feasible:
            effect = "deny"
            reason = "plan"
            rule_id = None
        elif request["archive"] not in retained:
            effect = "deny"
            reason = "retention"
            rule_id = None
        elif request["id"] not in covered:
            effect = "deny"
            reason = "audit"
            rule_id = None
        else:
            rule = _winning_rule(
                rules, request["resource"].strip(), request["action"].strip()
            )
            if rule is None:
                effect = "deny"
                rule_id = None
            else:
                effect = rule["effect"]
                rule_id = rule["id"]
            reason = "policy"

        decisions.append(
            {"id": request["id"], "effect": effect, "reason": reason, "rule_id": rule_id}
        )
        if effect == "allow":
            allow += 1
        else:
            deny += 1

    return {
        "name": name,
        "result": {"decisions": decisions, "allow": allow, "deny": deny},
    }

