import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def component_contracts():
    return sorted((ROOT / "products").rglob("contract.json"))


def main():
    paths = component_contracts()
    if not paths:
        raise SystemExit("no component contracts found")

    by_name = {}
    by_output = {}
    for path in paths:
        contract = json.loads(path.read_text(encoding="utf-8"))
        name = contract["name"]
        if name in by_name:
            raise SystemExit("duplicate contract name: " + name)
        by_name[name] = (path, contract)

        output = contract["output"]
        if output in by_output:
            raise SystemExit("duplicate contract output: " + output)
        by_output[output] = name

    deps = {name: set() for name in by_name}
    for name, (_, contract) in by_name.items():
        for input_path in contract.get("inputs", []):
            dep = by_output.get(input_path)
            if dep is not None and dep != name:
                deps[name].add(dep)

    visited = set()
    order = []

    def visit(name, stack):
        if name in visited:
            return
        if name in stack:
            raise SystemExit("component dependency cycle at " + name)
        stack.add(name)
        for dep in sorted(deps[name]):
            visit(dep, stack)
        stack.remove(name)
        visited.add(name)
        order.append(name)

    for name in sorted(by_name):
        visit(name, set())

    for name in order:
        path, contract = by_name[name]
        render = path.with_name("render.py")
        rel_contract = path.relative_to(ROOT)
        subprocess.run(
            [sys.executable, str(render), str(rel_contract)],
            cwd=ROOT,
            check=True,
        )

    subprocess.run([sys.executable, str(ROOT / "integrate.py")], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / "final_report.py")], cwd=ROOT, check=True)


if __name__ == "__main__":
    main()

